// Original animated GB/GBC cartridge. The header logo is the format signature.
module.exports=function cartridge({color=true,battery=false}={}){
 const rom=Buffer.alloc(32768),code=[],labels={},fixups=[];
 const emit=(...bytes)=>code.push(...bytes),label=name=>{labels[name]=0x150+code.length;};
 const jr=(op,name)=>{emit(op,0);fixups.push({at:code.length-1,name});};
 rom.set(Buffer.from('ceed6666cc0d000b03730083000c000d0008111f8889000edccc6ee6ddddd999bbbb67636e0eecccdddc999fbbb9333e','hex'),0x104);rom.set([0xc3,0x50,0x01],0x100);rom.write('TNS TEST',0x134);rom[0x143]=color?0x80:0;rom[0x147]=battery?0x1b:0;rom[0x148]=0;rom[0x149]=battery?2:0;
 emit(0xf3,0x31,0xff,0xdf,0xaf,0xe0,0x40,0x21,0,0x80,0x06,16);
 label('tile');emit(0x3e,0xf0,0x22,0x05);jr(0x20,'tile');
 emit(0x21,0,0x98,0x01,0,4);label('map');emit(0xaf,0x22,0x0b,0x78,0xb1);jr(0x20,'map');
 emit(0x3e,0x80,0xe0,0x68,0x21,0,0);const paletteAt=code.length-2;emit(0x06,8);label('palette');emit(0x2a,0xe0,0x69,0x05);jr(0x20,'palette');
 emit(0x3e,0xe4,0xe0,0x47,0x3e,0x91,0xe0,0x40,0x1e,0);
 label('vblank');emit(0xf0,0x44,0xfe,0x90);jr(0x38,'vblank');emit(0x1c,0x7b,0xe0,0x43);
 if(battery)emit(0x3e,0x0a,0xea,0,0,0x7b,0xea,0,0xa0);
 emit(0x3e,0x10,0xe0,0,0xf0,0,0xe6,1);if(battery)emit(0xea,1,0xa0);jr(0x28,'pressed');
 emit(0x3e,0xe4,0xe0,0x47,0x3e,0x80,0xe0,0x68,0x3e,0xff,0xe0,0x69,0x3e,0x7f,0xe0,0x69);jr(0x18,'after');
 label('pressed');emit(0x3e,0x1b,0xe0,0x47,0x3e,0x80,0xe0,0x68,0xaf,0xe0,0x69,0x3e,0x7c,0xe0,0x69);
 label('after');emit(0xf0,0x44,0xfe,0x90);jr(0x30,'after');jr(0x18,'vblank');
 label('paletteData');emit(255,127,31,0,224,3,0,0);code[paletteAt]=labels.paletteData&255;code[paletteAt+1]=labels.paletteData>>>8;
 for(const f of fixups){const distance=labels[f.name]-(0x150+f.at+1);if(distance< -128||distance>127)throw Error('Fixture branch out of range');code[f.at]=distance&255;}
 rom.set(code,0x150);let checksum=0;for(let i=0x134;i<=0x14c;i++)checksum=(checksum-rom[i]-1)&255;rom[0x14d]=checksum;
 let sum=0;for(let i=0;i<rom.length;i++)if(i!==0x14e&&i!==0x14f)sum=(sum+rom[i])&65535;rom.writeUInt16BE(sum,0x14e);return new Uint8Array(rom);
};
